INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1025, '数学', '三年级', '应用题', 3, '{"stem": "学校原来有650本图书，后又买来250本。把这些书平均分给6个年级，每个年级可分到多少本？三年级有5个班，每个班级平均可以分到多少本？", "options": null}', '150本；30本', '先求总数：650+250=900（本）；900÷6=150（本），每个年级分到150本；三年级有5个班，150÷5=30（本），每个班级分到30本。', 'paper', '["practice", "ykl3sx", "4.1"]', '["paper_png/ykl3_sx/p066.png"]', 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1025, '数学', '三年级', '填空', 3, '{"stem": "下列各个图形分别表示多少？△×□×○=540；△×□=60；□×○=180。△=（　），□=（　），○=（　）。", "options": null}', '3；20；9', '把△×□看作60：60×○=540，○=540÷60=9；把○=9代入□×○=180，□=20；把□=20代入△×□=60，△=3。检验：3×20×9=540，3×20=60，20×9=180，全部符合。', 'paper', '["practice", "ykl3sx", "4.1"]', '["paper_png/ykl3_sx/p066.png"]', 0);
